package com.tehang.enterpriserisk.api;
import com.tehang.enterpriserisk.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/risk-management") public class RiskController {private final RiskService risk;private final BatchCollectionService batches;private final EnterpriseImportService imports;private final WecomRobotService robot;private final AuthService auth;public RiskController(RiskService r,BatchCollectionService b,EnterpriseImportService i,WecomRobotService w,AuthService a){risk=r;batches=b;imports=i;robot=w;auth=a;}private void write(HttpServletRequest q){if(!auth.hasPermission((String)q.getAttribute("role"),"RISK_WRITE"))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"当前角色无操作权限");}private void admin(HttpServletRequest q){if(!auth.hasPermission((String)q.getAttribute("role"),"ADMIN_MANAGE"))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN,"需要管理员权限");}
 @GetMapping("/organization-risk")public List<Map<String,Object>>list(@RequestParam(required=false)String companyName,@RequestParam(required=false)String unifiedCreditCode,@RequestParam(required=false)String salesManager,@RequestParam(required=false)String batchNo,@RequestParam(required=false)String riskLevel,@RequestParam(required=false)String collectionStatus,@RequestParam(required=false)String batchRiskStatus,@RequestParam(required=false)String latestSuccessStart,@RequestParam(required=false)String latestSuccessEnd){return risk.list(companyName,unifiedCreditCode,salesManager,batchNo,riskLevel,collectionStatus,batchRiskStatus,latestSuccessStart,latestSuccessEnd);}@PatchMapping("/organization-risk/{id}/identity")public Map<String,Object>identity(@PathVariable long id,@Valid @RequestBody IdentityRequest r,HttpServletRequest q){write(q);return risk.updateIdentity(id,r.companyName(),r.unifiedCreditCode(),r.subjectType(),r.salesManager());}@PostMapping("/organization-risk/import")public Map<String,Object>one(@Valid @RequestBody ImportRequest r,HttpServletRequest q){write(q);return risk.upsert(r.unifiedCreditCode(),r.companyName(),r.subjectType(),r.monitoringEnabled(),"RISK_IMPORT",r.salesManager(),r.reactivateDeleted());}@GetMapping("/organization-risk/import-template")public void template(HttpServletResponse r)throws Exception{r.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");r.setHeader("Content-Disposition","attachment; filename=enterprise-import-template.xlsx");r.getOutputStream().write(imports.template());}@PostMapping(value="/organization-risk/import-file",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public Map<String,Object>file(@RequestParam("file")MultipartFile f,@RequestParam(defaultValue="false")boolean reactivateDeleted,HttpServletRequest q){write(q);return imports.importXlsx(f,reactivateDeleted);}@DeleteMapping("/organization-risk/{id}")public void delete(@PathVariable long id,HttpServletRequest q){write(q);risk.delete(id,String.valueOf(q.getAttribute("account")));}@PatchMapping("/organization-risk/{id}/monitoring")public Map<String,Object>monitor(@PathVariable long id,@RequestBody MonitoringRequest r,HttpServletRequest q){write(q);return risk.monitoring(id,r.enabled());}@PostMapping("/organization-risk/{id}/scan")public Map<String,Object>scan(@PathVariable long id,HttpServletRequest q){write(q);return risk.scanQueued(id,null);}@GetMapping("/organization-risk/{id}/snapshot")public Map<String,Object>snapshot(@PathVariable long id){return SnapshotNormalizer.normalize(risk.snapshot(id));}
 @GetMapping("/collection-runs/preview")public Map<String,Object>preview(HttpServletRequest q){write(q);return batches.preview();}@PostMapping("/collection-runs/execute")public Map<String,Object>execute(HttpServletRequest q){write(q);return batches.executeManual(String.valueOf(q.getAttribute("account")));}@GetMapping("/collection-runs/{id}")public Map<String,Object>run(@PathVariable long id){return batches.run(id);}@GetMapping("/collection-runs")public List<Map<String,Object>>runs(){return batches.runs();}@GetMapping("/collection-schedule")public Map<String,Object>schedule(){return batches.schedule();}@PutMapping("/collection-schedule")public void schedule(@RequestBody ScheduleRequest r,HttpServletRequest q){write(q);batches.saveSchedule(r.enabled(),r.frequency(),r.runTime(),r.dayOfWeek(),String.valueOf(q.getAttribute("account")));}
 @GetMapping("/collection-progress")public Map<String,Object>progress(HttpServletRequest q){write(q);return batches.progress();}
 @GetMapping("/wecom-robot")public Map<String,Object>robot(){return robot.config();}@GetMapping("/wecom-robot/logs")public List<Map<String,Object>>robotLogs(HttpServletRequest q){admin(q);return robot.logs();}@PutMapping("/wecom-robot")public void robot(@RequestBody RobotRequest r,HttpServletRequest q){admin(q);robot.save(r.enabled(),r.webhook(),r.riskLevels(),String.valueOf(q.getAttribute("account")));}@PostMapping("/wecom-robot/test")public void test(HttpServletRequest q){admin(q);robot.test();}
 @GetMapping("/models")public List<Map<String,Object>>models(){return risk.models();}@PutMapping("/models/{type}")public List<Map<String,Object>>models(@PathVariable String type,@Valid @RequestBody ModelRequest r,HttpServletRequest q){admin(q);return risk.saveModel(type,r.factors());}
 public record IdentityRequest(@NotBlank String companyName,@NotBlank String unifiedCreditCode,@NotBlank String subjectType,String salesManager){}public record ImportRequest(@NotBlank String unifiedCreditCode,@NotBlank String companyName,@NotBlank String salesManager,String subjectType,Boolean monitoringEnabled,boolean reactivateDeleted){}public record MonitoringRequest(boolean enabled){}public record ScheduleRequest(boolean enabled,@NotBlank String frequency,@NotBlank String runTime,Integer dayOfWeek){}public record RobotRequest(boolean enabled,String webhook,List<String> riskLevels){}public record ModelRequest(@NotNull List<Factor> factors){}public record Factor(@NotBlank String factorCode,@NotBlank String riskLevel,boolean enabled){public Factor(String factorCode,double legacyWeight,boolean enabled){this(factorCode,legacyWeight>=80?"CRITICAL":legacyWeight>=50?"HIGH":legacyWeight>=20?"MEDIUM":"LOW",enabled);}}
}
